def backfill_institution(apps, schema_editor):
    """按**业务对象**回填归属机构（不是按操作员）。

    存量行没有这条信息时留空 —— 空值在打印取单里等价于「只按区县放行」，
    与改动前的行为一致，不会因为回填不出来而误拒。
    """
    Capture = apps.get_model('business', 'Capture')
    Transfer = apps.get_model('business', 'Transfer')
    Treatment = apps.get_model('business', 'Treatment')
    Adoption = apps.get_model('business', 'Adoption')
    Euthanasia = apps.get_model('business', 'Euthanasia')
    OwnerReturn = apps.get_model('business', 'OwnerReturn')
    Release = apps.get_model('business', 'Release')

    # 捕捉单 → 捕捉点
    for row in Capture.objects.filter(institution__isnull=True).iterator():
        if row.shelter_id:
            row.institution_id = row.shelter_id
            row.save(update_fields=['institution'])

    # 转运单 → 发出捕捉点
    for row in Transfer.objects.filter(institution__isnull=True).iterator():
        if row.from_shelter_id:
            row.institution_id = row.from_shelter_id
            row.save(update_fields=['institution'])

    # 医院侧单据 → 医院
    for model in (Treatment, Adoption, Euthanasia):
        for row in model.objects.filter(institution__isnull=True).iterator():
            if row.hospital_id:
                row.institution_id = row.hospital_id
                row.save(update_fields=['institution'])

    # 领回 / 放归 → 动物当时所在的机构（医院优先，其次捕捉点）
    for model in (OwnerReturn, Release):
        for row in model.objects.filter(institution__isnull=True).select_related('pet').iterator():
            pet = row.pet
            if pet is None:
                continue
            inst_id = pet.hospital_id or pet.shelter_id
            if inst_id:
                row.institution_id = inst_id
                row.save(update_fields=['institution'])


def clear_institution(apps, schema_editor):
    for name in ('Capture', 'Transfer', 'Treatment', 'Adoption', 'Euthanasia',
                 'OwnerReturn', 'Release'):
        apps.get_model('business', name).objects.update(institution=None)


